package local.gxtodo.replica;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** One OS alarm covers all persisted tasks and survives removal of the WebView. */
public final class ReminderScheduler {
 static final String CHANNEL="task-reminders", PREF="reminder-delivery";
 static JSONArray tasks(Context c) throws Exception {AccountStore store=AccountStore.get(c);if(store.database(store.active()).initialized())return store.database(store.active()).tasks(false);String data=AccountStore.get(c).read(AccountStore.get(c).active());if(data.isEmpty())return new JSONArray();JSONArray roots=new JSONObject(data).getJSONArray("tasks"),result=new JSONArray();List<JSONObject> pending=new ArrayList<>();for(int i=0;i<roots.length();i++)pending.add(roots.getJSONObject(i));for(int i=0;i<pending.size()&&i<10000;i++){JSONObject task=pending.get(i);result.put(task);JSONArray children=task.optJSONArray("subtasks");if(children!=null)for(int j=0;j<children.length();j++)pending.add(children.getJSONObject(j));}return result;}
 static JSONArray reminderTasks(Context c)throws Exception{AccountStore store=AccountStore.get(c);return store.database(store.active()).initialized()?store.database(store.active()).tasks(true):tasks(c);}
 static NotificationManager manager(Context c){return (NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);}
 static void channel(Context c){NotificationChannel ch=new NotificationChannel(CHANNEL,"任务提醒",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("已设置时间的个人待办提醒");manager(c).createNotificationChannel(ch);}
 static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,0,new Intent(c,ReminderReceiver.class).setAction("local.gxtodo.REMIND"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static String key(JSONObject t){return t.optString("id")+"|"+t.optLong("reminderAt");}
 public static String status(Context c){channel(c);if(!manager(c).areNotificationsEnabled())return "系统通知尚未开启，请允许通知权限";if(manager(c).getNotificationChannel(CHANNEL).getImportance()==NotificationManager.IMPORTANCE_NONE)return "任务提醒通知渠道已关闭，请在系统设置中开启";AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);return Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms()?"通知已开启；未授权准时提醒，系统可能延迟送达":"系统通知与准时提醒已开启";}
 public static synchronized void refresh(Context c){channel(c);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.cancel(alarm(c));try{JSONArray tasks=reminderTasks(c);SharedPreferences prefs=c.getSharedPreferences(AccountStore.reminderPrefs(c),Context.MODE_PRIVATE);Set<String> active=new HashSet<>(),ids=new HashSet<>();long first=Long.MAX_VALUE;for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);if(t.optBoolean("done")||t.isNull("reminderAt")||t.optLong("reminderAt",0)<=0)continue;String key=key(t);active.add(key);ids.add(t.optString("id"));long saved=prefs.getLong(key,0);if(saved!=-1)first=Math.min(first,saved>0?saved:t.getLong("reminderAt"));}SharedPreferences.Editor edit=prefs.edit();for(String k:prefs.getAll().keySet())if(!active.contains(k))edit.remove(k);edit.apply();for(android.service.notification.StatusBarNotification n:manager(c).getActiveNotifications())if(n.getTag()!=null&&!ids.contains(n.getTag()))manager(c).cancel(n.getTag(),1);if(!manager(c).areNotificationsEnabled()||manager(c).getNotificationChannel(CHANNEL).getImportance()==NotificationManager.IMPORTANCE_NONE||first==Long.MAX_VALUE)return;long at=Math.max(System.currentTimeMillis()+500,first);if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c));else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c));}catch(Exception e){android.util.Log.e("GxTodoReminder","Cannot schedule saved reminders",e);}}
 static synchronized void fire(Context c){channel(c);if(!manager(c).areNotificationsEnabled())return;try{SharedPreferences prefs=c.getSharedPreferences(AccountStore.reminderPrefs(c),Context.MODE_PRIVATE);JSONArray tasks=reminderTasks(c);int delivered=0;for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);if(t.optBoolean("done")||t.isNull("reminderAt")||t.optLong("reminderAt",0)<=0)continue;String key=key(t);long saved=prefs.getLong(key,0),at=saved>0?saved:t.getLong("reminderAt");if(saved==-1||at>System.currentTimeMillis())continue;String id=t.getString("id");Intent open=new Intent(c,MainActivity.class).putExtra("taskId",id).putExtra("accountId",AccountStore.get(c).active()).setData(Uri.parse("gxtodo://task/"+Uri.encode(AccountStore.get(c).active()+"/"+id))).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent content=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent snooze=new Intent(c,ReminderReceiver.class).setAction("local.gxtodo.SNOOZE").putExtra("key",key).putExtra("taskId",id).putExtra("accountId",AccountStore.get(c).active()).setData(Uri.parse("gxtodo://snooze/"+Uri.encode(AccountStore.get(c).active()+"/"+key)));PendingIntent later=PendingIntent.getBroadcast(c,0,snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(c.getResources().getIdentifier("ic_notification","drawable",c.getPackageName())).setContentTitle("待办提醒 · "+AccountStore.get(c).activeName()).setContentText(t.optString("title")).setStyle(new Notification.BigTextStyle().bigText(t.optString("title"))).setContentIntent(content).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).addAction(new Notification.Action.Builder(null,"10 分钟后",later).build()).build();manager(c).notify(id,1,n);prefs.edit().putLong(key,-1).commit();if(++delivered>=5)break;}}catch(Exception e){android.util.Log.e("GxTodoReminder","Cannot deliver reminder",e);}refresh(c);}
}
